package com.bank.sparkeco.engine;

import com.bank.sparkeco.model.Txn;
import java.util.*;
import java.util.function.UnaryOperator;
import java.util.logging.Logger;

// Simulates Spark's in-memory, lineage-based execution across stages.
public class InMemoryEngine {
    private static final Logger log = Logger.getLogger(InMemoryEngine.class.getName());
    private final List<Txn> source;
    private final List<UnaryOperator<List<Txn>>> lineage = new ArrayList<>();

    public InMemoryEngine(List<Txn> source) { this.source = source; }

    public InMemoryEngine stage(UnaryOperator<List<Txn>> op) {
        lineage.add(op);           // record a stage (lazy) — kept in memory, no disk
        return this;
    }

    public List<Txn> run(boolean simulateFailure) {
        List<Txn> data = new ArrayList<>(source);
        for (int i = 0; i < lineage.size(); i++) {
            data = lineage.get(i).apply(data); // in-memory hand-off between stages
            if (simulateFailure && i == 0) {
                log.warning("Node failed after stage 0 → RECOMPUTE from lineage (not disk)");
                data = new ArrayList<>(source);
                for (int j = 0; j <= i; j++) data = lineage.get(j).apply(data);
            }
        }
        log.info("In-memory multi-stage job done (" + lineage.size() + " stages)");
        return data;
    }
}
