package com.bank.sparkeco.api;

import com.bank.sparkeco.model.Txn;
import java.math.BigDecimal;
import java.util.*;
import java.util.logging.Logger;

// One API surface mirroring Spark's four libraries on the SAME data.
public class UnifiedApi {
    private static final Logger log = Logger.getLogger(UnifiedApi.class.getName());
    private final List<Txn> data;

    public UnifiedApi(List<Txn> data) { this.data = data; }

    // Spark SQL — structured aggregation.
    public Map<String, BigDecimal> sqlTotalByAccount() {
        Map<String, BigDecimal> totals = new LinkedHashMap<>();
        for (Txn t : data) totals.merge(t.getAccountId(), t.getAmount(), BigDecimal::add);
        log.info("Spark SQL → totals " + totals);
        return totals;
    }

    // Structured Streaming — count events in a micro-batch.
    public long streamingCount() {
        log.info("Structured Streaming → micro-batch count = " + data.size());
        return data.size();
    }

    // MLlib — a toy classifier: flag high-value transactions.
    public List<String> mlClassify(BigDecimal threshold) {
        List<String> flagged = new ArrayList<>();
        for (Txn t : data) if (t.getAmount().compareTo(threshold) > 0) flagged.add(t.getAccountId());
        log.info("MLlib → high-value accounts " + flagged);
        return flagged;
    }

    // GraphX — find accounts linked by shared counterparties.
    public Set<String> graphLinkedAccounts(String counterparty) {
        Set<String> linked = new LinkedHashSet<>();
        for (Txn t : data) if (t.getCounterparty().equals(counterparty)) linked.add(t.getAccountId());
        log.info("GraphX → accounts linked via " + counterparty + " = " + linked);
        return linked;
    }
}
