package com.bank.sparkeco;

import com.bank.sparkeco.api.UnifiedApi;
import com.bank.sparkeco.engine.InMemoryEngine;
import com.bank.sparkeco.model.Txn;
import java.math.BigDecimal;
import java.util.*;
import java.util.logging.Logger;

public class SparkEcoDemo {
    private static final Logger log = Logger.getLogger(SparkEcoDemo.class.getName());

    public static void main(String[] args) {
        List<Txn> source = List.of(
            new Txn("SAV2001", new BigDecimal("1200"), "SHOP-A"),
            new Txn("SAV2001", new BigDecimal("150000"), "SHOP-B"),
            new Txn("CUR3001", new BigDecimal("5000"), "SHOP-A"),
            new Txn("CUR3001", new BigDecimal("2500"), "SHOP-C")
        );

        log.info("=== In-memory multi-stage engine (vs MapReduce disk I/O) ===");
        List<Txn> processed = new InMemoryEngine(source)
            .stage(list -> { list.removeIf(t -> t.getAmount().compareTo(BigDecimal.ZERO) <= 0); return list; })
            .stage(list -> list) // another stage, data stays in memory
            .run(true);          // simulate a node failure → lineage recompute

        log.info("=== Unified ecosystem on the SAME data ===");
        UnifiedApi api = new UnifiedApi(processed);
        api.sqlTotalByAccount();                         // Spark SQL
        api.streamingCount();                            // Structured Streaming
        api.mlClassify(new BigDecimal("100000"));        // MLlib
        api.graphLinkedAccounts("SHOP-A");               // GraphX
    }
}
